import React, { useState, useEffect } from 'react';

interface MediaRendererProps {
  src?: string;
  images?: string[];
  htmlLogs?: string[];
  alt?: string;
  className?: string;
}

export function MediaRenderer({ src, images, htmlLogs, alt = "", className = "" }: MediaRendererProps) {
  // If multiple images or htmlLogs are provided, render them as a column
  if (images || htmlLogs) {
    return (
      <div className={`flex flex-col items-center w-full gap-4 ${className}`}>
        {images?.map((img, idx) => (
          <MediaRenderer key={`img-${idx}`} src={img} alt={`${alt} - ${idx}`} />
        ))}
        {htmlLogs?.map((log, idx) => (
          <MediaRenderer key={`html-${idx}`} src={log.startsWith('data:') ? log : `data:text/html;charset=utf-8,${encodeURIComponent(log)}`} alt={`${alt} - log ${idx}`} />
        ))}
      </div>
    );
  }

  const isVideo = src?.startsWith('data:video');
  const isHtml = src?.startsWith('data:text/html') || (src && !src.startsWith('data:') && (src.includes('<p') || src.includes('<div')));

  const [parsedHtml, setParsedHtml] = useState<string | null>(null);
  const [parsedLog, setParsedLog] = useState<{tab:string, name: string, color: string, text: string}[] | null>(null);
  const [htmlMeta, setHtmlMeta] = useState<{ thumbnails?: Record<string, string>; bgImage?: string } | null>(null);

  useEffect(() => {
    if (isHtml) {
      try {
        const payload = src.split(',').slice(1).join(',');
        const decodedString = src.includes(';base64,')
          ? (() => {
              try {
                return decodeURIComponent(escape(atob(payload)));
              } catch {
                return atob(payload);
              }
            })()
          : decodeURIComponent(payload);

        const metaMatch = decodedString.match(/<!--\s*LOG_META:([A-Za-z0-9+/=]+)\s*-->/);
        if (metaMatch?.[1]) {
          try {
            const metaJson = decodeURIComponent(escape(atob(metaMatch[1])));
            setHtmlMeta(JSON.parse(metaJson));
          } catch {
            setHtmlMeta(null);
          }
        } else {
          setHtmlMeta(null);
        }

        const cleanedHtml = decodedString.replace(/<!--\s*LOG_META:[\s\S]*?-->/g, '');

        // Parse CCfolia HTML
        const parser = new DOMParser();
        const doc = parser.parseFromString(cleanedHtml, "text/html");
        
        // Extracts <p> elements (each represents a chat log)
        const pTags = Array.from(doc.querySelectorAll('p'));
        
        if (pTags.length > 0) {
            const logs = pTags.map(p => {
                const color = p.style.color || '#333333';
                const spans = Array.from(p.querySelectorAll('span'));
                
                if (spans.length >= 3) {
                    const tab = spans[0].textContent?.trim() || '';
                    let name = spans[1].textContent || '';
                    name = name.replace(/ :$/, '').trim(); 
                    const text = spans.slice(2).map(s => s.innerHTML).join(''); 
                    
                    return { tab, name, color, text };
                } else {
                    return { tab: 'system', name: 'System', color: '#888888', text: p.innerHTML };
                }
            });
            setParsedLog(logs);
        } else {
            setParsedHtml(decodedString);
        }
      } catch (e) {
        console.error('Failed to parse CCfolia HTML', e);
      }
    }
  }, [src, isHtml]);

  if (isVideo) {
    const isBackground = className.includes('object-cover') || className.includes('opacity');
    
    return (
      <video
        src={src}
        controls={!isBackground}
        autoPlay={true}
        loop={true}
        muted={true}
        playsInline={true}
        className={className || "max-w-full max-h-[80vh] w-auto h-auto object-contain rounded-lg shadow-2xl"}
      />
    );
  }

  if (isHtml) {
    if (parsedLog) {
      const thumbnails = htmlMeta?.thumbnails || {};
      const bgImage = htmlMeta?.bgImage || '';
      const groupedLogs: Array<{ kind: 'system' | 'info' | 'group'; tab: string; entries: typeof parsedLog }> = [];

      parsedLog.forEach((log) => {
        const tabText = log.tab.replace(/\[|\]/g, '').trim() || 'main';
        const isMain = tabText.toLowerCase() === 'main' || tabText === '메인';
        const isInfo = tabText === '정보' || tabText.toLowerCase().includes('info');
        const isSystem = tabText.toLowerCase() === 'system' || log.color === '#888888' || /(CC<=\s*\d+|choice|\b\d+d\d+\b)/i.test(log.text);

        if (isSystem) {
          groupedLogs.push({ kind: 'system', tab: tabText, entries: [log] });
          return;
        }

        const lastGroup = groupedLogs[groupedLogs.length - 1];
        const groupKind: 'info' | 'group' = isInfo ? 'info' : 'group';

        if (lastGroup && lastGroup.kind === groupKind && lastGroup.tab === tabText) {
          lastGroup.entries.push(log);
        } else {
          groupedLogs.push({ kind: groupKind, tab: tabText, entries: [log] });
        }

        if (isMain && lastGroup && lastGroup.kind === 'group' && lastGroup.tab === tabText) {
          return;
        }
      });

      const renderMessageCard = (log: (typeof parsedLog)[number]) => {
        const speakerThumb = thumbnails[log.name] || '';

        return (
          <article className="rounded-2xl border border-border/70 bg-card/95 shadow-sm overflow-hidden">
            <div className="flex items-center gap-3 px-4 py-3 border-b border-border/40">
              <div
                className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center bg-cover bg-center shrink-0 border border-border/10 shadow-sm"
                style={speakerThumb ? { backgroundImage: `url(${speakerThumb})` } : undefined}
              >
                {!speakerThumb && <span className="text-[10px] text-muted-foreground/60">No img</span>}
              </div>
              <div className="min-w-0 flex-1">
                <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-muted-foreground/50 leading-none mb-1">
                  {log.tab.replace(/\[|\]/g, '').trim() || 'MAIN'}
                </div>
                <div className="text-[15px] font-black leading-tight break-words" style={{ color: log.color }}>
                  {log.name || 'Unknown'}
                </div>
              </div>
            </div>
            <div className="px-4 py-4 text-[15px] leading-relaxed text-foreground/90 break-words ccfolia-text" dangerouslySetInnerHTML={{ __html: log.text }} />
          </article>
        );
      };

      // CCfolia log backup rendering - Script style, separated by tabs
      return (
        <div
          className={`w-full max-w-4xl mx-auto rounded-lg text-foreground flex flex-col ${className}`}
          style={{
            fontFamily: '"Malgun Gothic", "Apple SD Gothic Neo", sans-serif',
            backgroundImage: bgImage ? `url(${bgImage})` : undefined,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
          }}
        >
          <style dangerouslySetInnerHTML={{__html: `
            .ccfolia-text img {
              max-width: 100%;
              height: auto;
              border-radius: 8px;
              margin: 12px 0;
              box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
            }
            .log-avatar {
              width: 40px;
              height: 40px;
              border-radius: 12px;
              background-size: cover;
              background-position: center;
              background-color: rgb(226 232 240);
              flex-shrink: 0;
            }
          `}} />
          
          <div className="w-full space-y-4 bg-background/80 backdrop-blur-sm rounded-xl p-3 md:p-4">
            {groupedLogs.map((group, index) => {
              if (group.kind === 'system') {
                return (
                  <div key={`${group.tab}-${index}`} className="flex w-full justify-center py-2">
                    <div className="w-full max-w-[820px] rounded-2xl border border-slate-700/15 bg-gradient-to-br from-slate-900 to-slate-800 px-5 py-4 text-slate-50 shadow-lg overflow-hidden">
                      <div className="mb-2 text-[11px] font-bold uppercase tracking-[0.18em] text-slate-200/70">
                        {group.tab === 'system' ? 'SYSTEM' : group.tab}
                      </div>
                      <div className="text-[15px] leading-relaxed break-words overflow-wrap-anywhere ccfolia-text" style={{ color: 'inherit' }} dangerouslySetInnerHTML={{ __html: group.entries[0].text }} />
                    </div>
                  </div>
                );
              }

              if (group.kind === 'info') {
                return (
                  <section key={`${group.tab}-${index}`} className="rounded-2xl border-2 shadow-sm overflow-hidden" style={{ borderColor: group.entries[0].color, background: 'rgba(239, 246, 255, 0.72)' }}>
                    <div className="px-5 pt-4 pb-2 flex items-center gap-3 border-b" style={{ borderBottomColor: `${group.entries[0].color}30` }}>
                      <span className="text-[11px] font-bold px-2.5 py-1 rounded-full bg-background border uppercase tracking-[0.18em]" style={{ color: group.entries[0].color }}>
                        {group.tab}
                      </span>
                    </div>
                    <div className="p-4 grid gap-3">
                      {group.entries.map((log, entryIndex) => (
                        <div key={`${group.tab}-${index}-${entryIndex}`}>{renderMessageCard(log)}</div>
                      ))}
                    </div>
                  </section>
                );
              }

              const isMain = group.tab.toLowerCase() === 'main' || group.tab === '메인';

              if (isMain) {
                return (
                  <div key={`${group.tab}-${index}`} className="group rounded-2xl border border-border/70 bg-muted/20 overflow-hidden shadow-sm">
                    <div className="px-5 py-4 flex items-center gap-3 select-none bg-gradient-to-r from-white to-slate-50">
                      <span className="text-[11px] font-bold px-2.5 py-1 rounded-full bg-slate-900 text-white uppercase tracking-[0.18em]">{group.tab}</span>
                      <span className="text-sm font-semibold text-muted-foreground">{group.entries[0].name} {group.entries.length > 1 ? `외 ${group.entries.length - 1}개의 대화` : ''}</span>
                    </div>
                    <div className="p-4 grid gap-3 border-t border-border/50 bg-background/85">
                      {group.entries.map((log, entryIndex) => (
                        <div key={`${group.tab}-${index}-${entryIndex}`}>{renderMessageCard(log)}</div>
                      ))}
                    </div>
                  </div>
                );
              }

              return (
                <details key={`${group.tab}-${index}`} className="group rounded-2xl border border-border/70 bg-muted/20 overflow-hidden shadow-sm" open={group.entries.length < 5}>
                  <summary className="cursor-pointer list-none px-5 py-4 flex items-center gap-3 select-none bg-gradient-to-r from-white to-slate-50">
                    <span className="text-[11px] font-bold px-2.5 py-1 rounded-full bg-slate-900 text-white uppercase tracking-[0.18em]">{group.tab}</span>
                    <span className="text-sm font-semibold text-muted-foreground">{group.entries[0].name} {group.entries.length > 1 ? `외 ${group.entries.length - 1}개의 대화` : ''}</span>
                    <span className="ml-auto text-xs font-bold text-slate-400 group-open:hidden">펼치기</span>
                    <span className="ml-auto text-xs font-bold text-slate-400 hidden group-open:inline">접기</span>
                  </summary>
                  <div className="p-4 grid gap-3 border-t border-border/50 bg-background/85">
                    {group.entries.map((log, entryIndex) => (
                      <div key={`${group.tab}-${index}-${entryIndex}`}>{renderMessageCard(log)}</div>
                    ))}
                  </div>
                </details>
              );
            })}
          </div>
        </div>
      );
    }

    // Fallback HTML iframe
    return (
      <div className={`overflow-hidden rounded-lg bg-white shadow-xl ${className}`} style={{ width: '100%', maxWidth: '800px', margin: '0 auto', height: 'auto', minHeight: '80vh' }}>
        <iframe
          srcDoc={parsedHtml || ''}
          className="w-full h-full min-h-[80vh] border-none"
          title={alt}
          sandbox="allow-same-origin allow-scripts"
        />
      </div>
    );
  }

  // Fallback to underlying image
  const imgClasses = className || "max-w-full max-h-[80vh] w-auto h-auto object-contain rounded-lg shadow-2xl";
  return <img src={src} alt={alt} className={imgClasses} />;
}
