"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { ArrowLeft, ZoomIn, Download, Maximize2, X } from 'lucide-react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { MediaRenderer } from '@/components/media-renderer';
import { Button } from '@/components/ui/button';

export default function IllustrationDetailPage() {
  const params = useParams();
  const categoryParam = params.category as string;
  const idParam = params.id as string;
  const { illustrations, categories } = useAppStore();
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [selectedImg, setSelectedImg] = useState<string | null>(null);

  const item = illustrations.find(c => c.id === idParam);
  const currentCategoryObj = categories.find(c => c.id === categoryParam);
  const categoryTitle = currentCategoryObj ? currentCategoryObj.label : '일러스트';

  if (!item) {
    return (
      <div className="min-h-screen bg-background">
        <Sidebar />
        <main className="min-h-screen pt-16 lg:pt-0 flex justify-center items-center">
          <p>작품을 찾을 수 없습니다.</p>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Sidebar />
      <main className="min-h-screen pt-16 lg:pt-0">
        <div className="max-w-5xl mx-auto px-4 md:px-8 py-10">
          <Link href={/illustrations/} className="mb-6 inline-flex items-center text-sm font-bold text-muted-foreground hover:text-primary transition-colors group">
            <ArrowLeft className="mr-2 h-4 w-4 group-hover:-translate-x-1 transition-transform" />
            {categoryTitle} 목록
          </Link>
          
          <div className="flex flex-col gap-8">
             {/* Header */}
             <div className="space-y-4">
                <div className="flex items-center gap-2">
                   <span className="px-2 py-0.5 rounded bg-primary/10 text-primary text-[10px] font-black uppercase tracking-wider">Illustration</span>
                   <span className="text-xs text-muted-foreground">{new Date(item.createdAt).toLocaleDateString()}</span>
                </div>
                <h1 className="text-3xl md:text-4xl font-black tracking-tight text-slate-900 dark:text-slate-50">{item.title}</h1>
                <p className="text-slate-500 dark:text-slate-400 leading-relaxed font-medium whitespace-pre-wrap">{item.description}</p>
             </div>

             {/* Content */}
             <div className="bg-slate-50 dark:bg-slate-900/50 rounded-3xl p-4 md:p-8 border border-slate-200/60 dark:border-slate-800/60">
                <MediaRenderer images={item.images} htmlLogs={item.htmlLogs} alt={item.title} />
             </div>

             {/* Footer Info */}
             <div className="flex flex-wrap gap-2 py-6 border-t border-border">
                {item.tags?.map(tag => (
                  <span key={tag} className="px-3 py-1.5 rounded-full bg-muted text-sm font-bold text-muted-foreground">#{tag}</span>
                ))}
             </div>
          </div>
        </div>
      </main>

      {/* Lightbox / Zoom (Optional enhancement) */}
      {selectedImg && (
        <div className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4" onClick={() => setSelectedImg(null)}>
           <button className="absolute top-6 right-6 text-white hover:rotate-90 transition-transform"><X className="w-8 h-8"/></button>
           <img src={selectedImg} className="max-w-full max-h-full object-contain shadow-2xl" alt="zoom" />
        </div>
      )}
    </div>
  );
}
